const req = $json;
const body = req.body ?? req;
const required = ['tenant_id','workflow_id','invocation_id','idempotency_key','schema_version'];
for (const key of required) {
  if (!body[key]) throw new Error(`Missing ${key}`);
}
if (!String(body.schema_version).startsWith('2.')) throw new Error('Unsupported Jahorin n8n schema');
return [{
  json: {
    ...body,
    received_at: new Date().toISOString(),
    phase: 'acting',
    input: body.input ?? {},
    memory_context: Array.isArray(body.memory_context) ? body.memory_context : [],
  }
}];

const input = $json.input ?? {};
const content = String(input.content ?? input.memory ?? input.summary ?? '').trim();
if (!content) throw new Error('Memory content is required');
return [{
  json: {
    workflow_id: $json.workflow_id,
    status: 'completed',
    result: { accepted: true, kind: input.kind ?? 'explicit' },
    evidence: [{ kind: 'memory_write', source: 'thoth', at: new Date().toISOString() }],
    memory_candidates: [{
      persist: true,
      provenance: input.provenance ?? 'explicit_user',
      kind: input.kind ?? 'explicit',
      scope: input.scope ?? 'persistent',
      importance: input.importance ?? 0.7,
      content,
      metadata: input.metadata ?? {},
    }],
  }
}];
